/* ─── Table ─── */
.table-wrap { overflow-x: auto; max-width: 100%; }
.table { width: 100%; border-collapse: collapse; font-size: var(--text-sm); }
.table th { text-align: start; font-size: var(--text-xs); font-weight: 400; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); padding-block: var(--s3); padding-inline: 0 var(--s4); border-bottom: 1px solid var(--foreground); white-space: nowrap; }
.table td { padding-block: var(--s3); padding-inline: 0 var(--s4); border-bottom: 1px solid var(--rule); vertical-align: top; }
.table tbody tr:hover { background: var(--wash); }
.table .num { text-align: end; padding-inline-end: 0; padding-inline-start: var(--s4); }
.table caption { text-align: start; padding-bottom: var(--s3); color: var(--muted); font-size: var(--text-xs); }

/* Checkbox, radio and switch built on Radix (button + data-state). The legacy .choice/.switch classes still style native inputs. */
.checkbox, .radio { appearance: none; flex: none; width: 18px; height: 18px; margin: 0; padding: 0; display: inline-grid; place-items: center; border: 1px solid var(--foreground); background: transparent; color: var(--background); cursor: pointer; transition: background var(--fast); }
.radio { border-radius: var(--round); }
.checkbox[data-state="checked"], .checkbox[data-state="indeterminate"], .radio[data-state="checked"] { background: var(--foreground); }
.checkbox:disabled, .radio:disabled, .sw:disabled { opacity: 0.5; cursor: not-allowed; }
.checkbox[aria-invalid="true"], .radio[aria-invalid="true"] { border-color: var(--danger); }
.checkbox-mark { width: 10px; height: 10px; }
.radio-dot { width: 8px; height: 8px; border-radius: var(--round); background: var(--background); }
.radio-group { display: grid; gap: var(--s3); }
.radio-group[data-orientation="horizontal"] { display: flex; flex-wrap: wrap; gap: var(--s5); }
.sw { flex: none; width: 36px; height: 20px; padding: 0; border: 1px solid var(--foreground); background: transparent; position: relative; cursor: pointer; transition: background var(--fast); }
.sw[data-state="checked"] { background: var(--foreground); }
.sw-thumb { display: block; width: 12px; height: 12px; background: var(--foreground); transform: translateX(calc(3px * var(--dir, 1))); transition: transform var(--base) var(--ease), background var(--fast); }
.sw[data-state="checked"] .sw-thumb { transform: translateX(calc(19px * var(--dir, 1))); background: var(--background); }

/* ─── Navigation: breadcrumb, pager, steps, top bar ─── */
.crumbs { min-width: 0; display: flex; flex-wrap: wrap; gap: var(--s2); font-size: var(--text-sm); color: var(--muted); }
.crumbs li + li::before { content: "/"; margin-inline-end: var(--s2); color: var(--ink-3); }
.crumbs [aria-current="page"] { color: var(--foreground); }
.pager { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); font-size: var(--text-sm); }
.pager a, .pager button { min-width: 36px; padding: var(--s2) var(--s3); text-align: center; border: 1px solid var(--rule); text-decoration: none; }
.pager a:hover, .pager button:hover:not(:disabled) { border-color: var(--foreground); }
.pager [aria-current="page"] { background: var(--foreground); color: var(--background); border-color: var(--foreground); }
.pager button:disabled { opacity: 0.5; cursor: not-allowed; }
.steps { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: var(--s3); counter-reset: step; }
.step { counter-increment: step; padding-top: var(--s3); border-top: 2px solid var(--rule); font-size: var(--text-sm); color: var(--muted); }
.step::before { content: counter(step, decimal-leading-zero); display: block; font-size: var(--text-xs); }
.step[data-state="done"] { border-top-color: var(--foreground); color: var(--foreground); }
.step[aria-current="step"] { border-top-color: var(--accent); color: var(--foreground); font-weight: 500; }
.topbar { display: flex; align-items: center; gap: var(--s5); padding: var(--s4) var(--s5); border-bottom: 1px solid var(--rule); flex-wrap: wrap; }
.topbar .brand { padding: 0; }
.topbar-nav { display: flex; flex-wrap: wrap; gap: var(--s5); margin-inline-end: auto; font-size: var(--text-sm); }
.topbar-nav a { text-decoration: none; color: var(--muted); }
.topbar-nav a:hover, .topbar-nav a[aria-current="page"] { color: var(--foreground); }
.tab[aria-selected="true"] { color: var(--foreground); box-shadow: inset 0 2px 0 var(--foreground); }
.tabpanel { padding-top: var(--s5); }
.tabpanel[hidden] { display: none; }
[dir="rtl"] .crumbs li + li::before { display: inline-block; transform: scaleX(-1); }

/* Empty state: centred message inside a dashed frame. */
.empty { display: grid; justify-items: center; gap: var(--s3); padding: var(--s7) var(--s5); text-align: center; border: 1px dashed var(--rule); }
.empty-icon { color: var(--muted); font-size: var(--text-lg); }
.empty-title { font-size: var(--text-lg); font-weight: 500; }
.empty-description { color: var(--muted); font-size: var(--text-sm); max-width: var(--measure); }
.empty-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--s3); margin-top: var(--s2); }

/* Data table: builds on .table; adds sort buttons, a checkbox column and a footer. */
.data-table-sort-btn { display: inline-flex; align-items: center; gap: var(--s2); font: inherit; text-transform: inherit; letter-spacing: inherit; color: inherit; padding: var(--s1) 0; min-height: 24px; cursor: pointer; }
.data-table-sort-btn:hover { color: var(--foreground); }
.data-table-sort { width: 0.9em; height: 0.9em; opacity: 0.4; }
.data-table-sort[data-direction] { opacity: 1; color: var(--foreground); }
.data-table-sort[data-direction="desc"] { transform: rotate(180deg); }
.data-table .data-table-check { width: 1%; padding-inline-end: var(--s3); }
.data-table .table tbody tr[data-state="selected"] { background: var(--wash); }
.data-table-footer { display: flex; justify-content: flex-end; padding-top: var(--s4); }
.data-table .table .empty { border: 0; }

usage:
import {DataTable, type DataTableColumn} from '@monoline/react';

interface Person {id: string; name: string; role: string; projects: number}

const people: Person[] = [
  ['Ada Lovelace', 'Engineer', 4], ['Grace Hopper', 'Admiral', 9], ['Alan Turing', 'Researcher', 6], ['Katherine Johnson', 'Mathematician', 7],
  ['Linus Torvalds', 'Maintainer', 12], ['Margaret Hamilton', 'Director', 5], ['Dennis Ritchie', 'Engineer', 3], ['Barbara Liskov', 'Professor', 8],
].map(([name, role, projects], i) => ({id: String(i), name: name as string, role: role as string, projects: projects as number}));

const columns: DataTableColumn<Person>[] = [
  {id: 'name', header: 'Name', sortable: true},
  {id: 'role', header: 'Role', sortable: true},
  {id: 'projects', header: 'Projects', sortable: true, align: 'end'},
];

<DataTable
  label="Team"
  columns={columns}
  data={people}
  defaultSort={{id: 'name', direction: 'asc'}}
/>

